+type evidenceField struct { text, pointer, role, timestamp string; line int }
+type evidenceCandidates struct {
+ Spans []evidenceSpan
+ Warnings []string
+ State string
+ InputTruncated bool
+ SessionsScanned int
+ SessionsMatched int
+}
+
+func evidenceHash(b []byte) string { h:=sha256.Sum256(b); return hex.EncodeToString(h[:]) }
+
+// Empty-line boundaries preserve code fences, table rows and original CRLF.
+func evidenceBlocks(text string) [][2]int {
+ var out [][2]int
+ start, offset := 0,0
+ fence := ""
+ for _, line := range strings.SplitAfter(text,"\n") {
+  trimmed:=strings.TrimLeft(line," "); indent:=len(line)-len(trimmed)
+  if indent<=3 && len(trimmed)>=3 && (strings.HasPrefix(trimmed,"```") || strings.HasPrefix(trimmed,"~~~")) {
+   n:=0; for n<len(trimmed) && trimmed[n]==trimmed[0] { n++ }
+   if fence=="" { fence=trimmed[:n] } else if fence[0]==trimmed[0] && n>=len(fence) && strings.TrimSpace(trimmed[n:])=="" { fence="" }
+  }
+  if strings.TrimSpace(line)=="" && fence=="" {
+   if strings.TrimSpace(text[start:offset])!="" { out=append(out,[2]int{start,offset}) }
+   start=offset+len(line)
+  }
+  offset+=len(line)
+ }
+ if strings.TrimSpace(text[start:offset])!="" { out=append(out,[2]int{start,offset}) }
+ return out
+}
+
+// Explicit schemas prevent hidden reasoning, tool output and arbitrary metadata
+// from becoming conversation evidence. String values are never normalized.
+func evidenceJSONFields(obj map[string]any, prefix string, line int) []evidenceField {
+ var fields []evidenceField
+ timestamp:=jsonString(obj["timestamp"])
+ add:=func(value any, pointer, role string) { if s,ok:=value.(string); ok && strings.TrimSpace(s)!="" { fields=append(fields,evidenceField{s,prefix+pointer,role,timestamp,line}) } }
+ content:=func(value any,pointer,role string) {
+  if role!="user" && role!="assistant" { return }
+  if _,ok:=value.(string); ok { add(value,pointer,role); return }
+  if list,ok:=value.([]any); ok { for i,v:=range list { block:=jsonMap(v); switch jsonString(block["type"]) { case "text","input_text","output_text": add(block["text"],fmt.Sprintf("%s/%d/text",pointer,i),role) } } }
+ }
+ switch jsonString(obj["type"]) {
+ case "event_msg":
+  p:=jsonMap(obj["payload"]); switch jsonString(p["type"]) { case "user_message": add(p["message"],"/payload/message","user"); case "agent_message": add(p["message"],"/payload/message","assistant") }
+ case "response_item":
+  p:=jsonMap(obj["payload"]); if jsonString(p["type"])=="message" && jsonString(p["phase"])!="analysis" { content(p["content"],"/payload/content",jsonString(p["role"])) }
+ case "agent_message": add(obj["message"],"/message","assistant")
+ case "user","assistant","message":
+  m:=jsonMap(obj["message"]); role:=jsonString(m["role"]); if role=="" { role=jsonString(obj["type"]) }; content(m["content"],"/message/content",role)
+ case "":
