+func collectEvidence(ctx context.Context, brainDir, branch, query string, limit int) (evidenceCandidates,error) {
+ c:=evidenceCandidates{Spans:[]evidenceSpan{},State:"available"}
+ manifest,err:=loadBrainManifest(brainDir)
+ if err!=nil { c.State="unavailable"; c.Warnings=append(c.Warnings,"session manifest unavailable"); return c,nil }
+ if manifest==nil || manifest.Sources==nil || manifest.Sources.Sessions==nil { c.State="unavailable"; c.Warnings=append(c.Warnings,"no canonical sessions declared; absence of evidence is not evidence of absence"); return c,nil }
