+  for _,f:=range rankFacts(guardFactRecords(guard,facts),query,limit,false) { for _,a:=range f.Provenance { if !guard.blocksFactAnchor(a) { anchored[a.SessionID]=true } } }
+ }
+ if manifest.Sources.Facts!=nil { if warning:=missingFactStoreWarningForBranch(brainDir,manifest.Sources.Facts,branch);warning!="" { c.Warnings=append(c.Warnings,warning) } }
